# ! [doc = " Platform-specific, assembly instructions to avoid"] # ! [doc = " intermediate rounding on architectures with FPUs."] use split_decls_genesis :: ourprelude :: * ; pub (super) use fpu_precision :: set_precision ; #[cfg (all (target_arch = "x86" , not (target_feature = "sse2")))] mod fpu_precision { use core :: arch :: asm ; #[doc = " A structure used to preserve the original value of the FPU control word, so that it can be"] #[doc = " restored when the structure is dropped."] #[doc = ""] #[doc = " The x87 FPU is a 16-bits register whose fields are as follows:"] #[doc = ""] #[doc = " | 12-15 | 10-11 | 8-9 | 6-7 |  5 |  4 |  3 |  2 |  1 |  0 |"] #[doc = " |------:|------:|----:|----:|---:|---:|---:|---:|---:|---:|"] #[doc = " |       | RC    | PC  |     | PM | UM | OM | ZM | DM | IM |"] #[doc = ""] #[doc = " The documentation for all of the fields is available in the IA-32 Architectures Software"] #[doc = " Developer's Manual (Volume 1)."] #[doc = ""] #[doc = " The only field which is relevant for the following code is PC, Precision Control. This"] #[doc = " field determines the precision of the operations performed by the FPU. It can be set to:"] #[doc = "  - 0b00, single precision i.e., 32-bits"] #[doc = "  - 0b10, double precision i.e., 64-bits"] #[doc = "  - 0b11, double extended precision i.e., 80-bits (default state)"] #[doc = " The 0b01 value is reserved and should not be used."] pub (crate) struct FPUControlWord (u16) ; fn set_cw (cw : u16) { unsafe { asm ! ("fldcw word ptr [{}]" , in (reg) & cw , options (nostack) ,) } } #[doc = " Sets the precision field of the FPU to `T` and returns a `FPUControlWord`."] pub (crate) fn set_precision < T > () -> FPUControlWord { let mut cw = 0_u16 ; let cw_precision = match size_of :: < T > () { 4 => 0x0000 , 8 => 0x0200 , _ => 0x0300 , } ; unsafe { asm ! ("fnstcw word ptr [{}]" , in (reg) & mut cw , options (nostack) ,) } set_cw ((cw & 0xFCFF) | cw_precision) ; FPUControlWord (cw) } impl Drop for FPUControlWord { fn drop (& mut self) { set_cw (self . 0) } } } #[cfg (any (not (target_arch = "x86") , target_feature = "sse2"))] mod fpu_precision { pub (crate) fn set_precision < T > () { } }